const dropped5 = d5.drop("congee", null), plated5 = d5.plateNow(0);
b5.record.drawImage.length = 0;
b5.pump(1);
const pbox0 = b5.B.plateBox(0);
const inBox0 = (name) => b5.record.drawImage.filter(r => r.src.split("/").pop() === name &&
  (r.dx + r.dw / 2) >= pbox0.x && (r.dx + r.dw / 2) <= pbox0.x + pbox0.w &&
  (r.dy + r.dh / 2) >= pbox0.y && (r.dy + r.dh / 2) <= pbox0.y + pbox0.h);
A(inBox0("congee.png").length > 0,
  "白粥落盘 → 盘位是「plate_empty + 食物贴图」（没有专属盘贴图的食材照旧这样画）",
  "drop=" + dropped5 + " plateNow=" + plated5 + " plateTex=" + d5.plates().map(p => p.food + ":" + p.state).join(",") +
  " 盘位里的图：" + b5.record.drawImage.filter(r => (r.dx + r.dw / 2) >= pbox0.x && (r.dx + r.dw / 2) <= pbox0.x + pbox0.w).map(r => r.src.split("/").pop()).join(","));
